#include <iostream>
int main() {
    int a = 0, b = 0;
    std::cin >> a >> b;
    std::cout << a + b << "\n";
}

int x = 5;
int y = x + 1;
x = 9;
// x is 9; y is still 6.

int sum = 0;
for (int i = 1; i <= 5; ++i) {
    sum += i;
}
std::cout << sum << "\n";

int square(int x) {
    return x * x;
}

#include <vector>
std::vector<int> values{8, 3, 6};
int best = values[0]; // assumes nonempty
for (int value : values) {
    if (value > best) best = value;
}

